Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",

  "title": {
    "text": "Agent Performance – APE vs Target",
    "fontSize": 24,
    "fontWeight": "bold",
    "anchor": "start",
    "offset": 12
  },

  "width": "container",
  "height": 780,

  "data": {
    "name": "dataset"
  },

  "params": [
    {
      "name": "pageNumber",
      "value": 1,
      "bind": {
        "input": "select",
        "options": [1, 2, 3, 4, 5, 6, 7, 8],
        "labels": [
          "Page 1 — Agents 1–20",
          "Page 2 — Agents 21–40",
          "Page 3 — Agents 41–60",
          "Page 4 — Agents 61–80",
          "Page 5 — Agents 81–100",
          "Page 6 — Agents 101–120",
          "Page 7 — Agents 121–140",
          "Page 8 — Agents 141–158"
        ],
        "name": "AGENT PAGE: "
      }
    },

    {
      "name": "agentSelect",
      "select": {
        "type": "point",
        "fields": ["agent_name"],
        "on": "click",
        "clear": "dblclick"
      }
    }
  ],

  "transform": [
    {
      "filter": "datum.agent_name != null && datum.agent_name != ''''"
    },

    {
      "window": [
        {
          "op": "rank",
          "as": "agent_rank"
        }
      ],
      "sort": [
        {
          "field": "Total APE",
          "order": "descending"
        }
      ]
    },

    {
      "filter": "datum.agent_rank > (pageNumber - 1) * 20 && datum.agent_rank <= pageNumber * 20"
    }
  ],

  "mark": {
    "type": "bar",
    "cornerRadiusEnd": 3
  },

  "encoding": {
    "y": {
      "field": "agent_name",
      "type": "nominal",

      "sort": {
        "field": "Total APE",
        "order": "descending"
      },

      "scale": {
        "paddingInner": 0.35,
        "paddingOuter": 0.15
      },

      "axis": {
        "title": "Agent",
        "titleFontSize": 18,
        "titleFontWeight": "bold",
        "labelFontSize": 16,
        "labelFontWeight": "bold",
        "labelLimit": 180,
        "labelPadding": 7,
        "ticks": false,
        "domain": false
      }
    },

    "x": {
      "field": "Total APE",
      "type": "quantitative",
      "aggregate": "sum",

      "axis": {
        "title": "APE",
        "titleFontSize": 18,
        "titleFontWeight": "bold",
        "labelFontSize": 15,
        "labelFontWeight": "bold",
        "format": "~s",
        "grid": true
      }
    },

    "color": {
      "condition": [
        {
          "test": "datum[''APE vs Target %''] >= 1",
          "value": "#2E7D32"
        },
        {
          "test": "datum[''APE vs Target %''] >= 0.8",
          "value": "#F9A825"
        }
      ],
      "value": "#C62828"
    },

    "opacity": {
      "condition": {
        "param": "agentSelect",
        "value": 1
      },
      "value": 0.9
    },

    "tooltip": [
      {
        "field": "agent_name",
        "type": "nominal",
        "title": "Agent"
      },
      {
        "field": "agent_rank",
        "type": "quantitative",
        "title": "Overall Rank",
        "format": "0"
      },
      {
        "field": "Total APE",
        "type": "quantitative",
        "aggregate": "sum",
        "title": "APE",
        "format": ",.0f"
      },
      {
        "field": "APE vs Target %",
        "type": "quantitative",
        "title": "vs Target",
        "format": ".0%"
      }
    ]
  },

  "config": {
    "background": "white",

    "view": {
      "stroke": null
    },

    "axis": {
      "labelColor": "#1F2937",
      "titleColor": "#111827",
      "gridColor": "#E5E7EB"
    },

    "scale": {
      "bandPaddingInner": 0.35,
      "bandPaddingOuter": 0.15
    }
  }
}'
